from __future__ import annotations
from abc_creative_gold_v5_101_200_support import make_spec, register_craft
FACTS={
"Architect":"Design professional plans buildings/spaces with drawings, codes, structure, accessibility, and collaboration; architect is not the builder operating site tools.","Builder":"Construction worker/contractor turns plans into physical work with trades and safety systems; exact role varies by project.","Chef":"Professional cook plans/prepares food and manages kitchen processes; hot/sharp equipment and food safety require trained work.","Dentist":"Licensed oral-health clinician examines and treats teeth/gums; procedures use specialized instruments and consent.","Electrician":"Trained tradesperson installs/tests electrical systems; live electricity requires isolation, testing, and professional procedures.","Firefighter":"Emergency responder handles fires, rescue, hazards, and prevention; scenes require protective gear, team command, and public distance.","Garbage Collector":"Worker collects waste/recycling; moving trucks, compactors, traffic, and sharp waste create safety zones.","Hairdresser":"Professional cuts/styles/treats hair; scissors, heat, chemicals, and hygiene require trained handling.","Inspector":"Person checks work, safety, quality, or compliance against standards; exact authority depends on field.","Judge":"Legal official presides over court proceedings and applies law/procedure; does not investigate or police streets.","Kitchen Worker":"Broad kitchen role supports prep, cooking, cleaning, service, or dish work; exact tasks and training vary.","Librarian":"Information professional organizes collections, helps users find resources, and supports literacy/research; role is more than shelving books.","Mechanic":"Technician diagnoses, maintains, and repairs machines/vehicles; tools, lifts, fluids, and moving parts require trained work.","News Reporter":"Journalist gathers, verifies, and communicates information; responsible reporting distinguishes observation, sources, and claims.","Optometrist":"Eye-care professional examines vision/eye health and prescribes lenses in many jurisdictions; scope varies by law.","Police Officer":"Law-enforcement professional performs duties under law/training; emergency response is not a child imitation role.","Quality Inspector":"Worker checks products/processes against specifications using observation, measurement, or tests; inspection is evidence-based.","Rescue Worker":"Trained responder assists people in emergencies using specialized teams, equipment, and risk assessment.","Scientist":"Person investigates questions with systematic observation, measurement, experiments, models, or analysis; science includes revising ideas from evidence.","Teacher":"Education professional plans learning, guides practice, assesses understanding, and supports students; teaching is not just giving answers.","Utility Worker":"Worker maintains public services such as power, water, gas, telecom, or streets; hazards and training depend on utility.","Volunteer":"Person gives time/service without ordinary wages for a cause or organization; volunteers still follow training, role limits, and supervision.","Waiter":"Restaurant server takes orders, communicates with kitchen, serves food/drinks, and supports guests; hot plates/allergen communication require care.","X-ray Technician":"Radiologic technologist/technician operates diagnostic imaging under professional protocols; controlled radiation and patient positioning require training.","Yard Worker":"Worker maintains outdoor grounds through mowing, pruning, cleanup, or landscaping; powered/sharp tools require adult professional handling.","Zumba Instructor":"Fitness instructor leads Zumba-branded dance exercise classes; intensity and movements are adapted to participants.","Ambulance":"Emergency medical vehicle, not a job title; it carries EMTs/paramedics, patients, and equipment.","Baker":"Food professional produces breads/pastries using combining, fermentation, shaping, ovens, and food-safety systems.","EMT":"Emergency medical technician assesses and provides prehospital emergency care within local training/scope, often working with ambulance teams.","Farmer":"Person manages crops, livestock, land, equipment, or farm business; tasks vary greatly by farm type.","Gardener":"Person grows and maintains plants/landscapes through planting, watering, pruning, soil care, and observation.","Interpreter":"Professional conveys meaning between languages in real time; accuracy, context, and confidentiality matter.","Janitor":"Worker cleans and maintains buildings, handles waste/supplies, and may report facility problems; chemicals/equipment need safe procedures.","Kindergarten Teacher":"Early-childhood teacher structures play, language, routines, social learning, and foundational skills for young learners.","Lifeguard":"Trained safety worker watches designated swimming areas, enforces rules, and responds to aquatic emergencies; supervision never replaces caregiver attention for young children.","Mail Carrier":"Postal worker sorts and delivers letters/parcels along a route; addresses and secure mail handling guide the job.","Officer":"Broad title for an official role; the word alone does not guarantee police, military, or any one occupation.","Plumber":"Skilled tradesperson installs/repairs water, drainage, and related piping systems; tools and codes require training.","Receptionist":"Front-desk worker greets visitors, handles appointments/messages, and routes information while protecting privacy.","Umpire":"Sports official applies game rules and makes calls; the specific sport determines positioning and signals.","Veterinarian":"Licensed animal doctor diagnoses/treats animal health; safe restraint, medicine, surgery, and species knowledge require professional training.","Xylophone Teacher":"Music teacher using xylophone/tuned percussion for pitch, rhythm, and technique; the label is a teaching role, not a unique profession license.","Courier":"Worker transports documents/parcels between locations; route, custody, and delivery confirmation may matter.","Doctor":"Licensed medical physician diagnoses/treats illness and manages health within training/specialty; clinical procedures require consent and evidence.","Helper":"General relationship word for someone assisting; it is not one formal profession or fixed skill set.","Nurse":"Licensed healthcare professional assesses, monitors, educates, and provides care within credential and setting.","Quartermaster":"Role manages supplies, equipment, and logistics in organizations.","Taxi Driver":"Licensed/authorized driver transports paying passengers; road safety, route, and local fare regulations apply.","Welder":"Trained worker joins metals using heat/arc/pressure processes; intense light, heat, fumes, fire, and electricity require PPE and controlled work.","Yoga Teacher":"Instructor guides yoga postures, breathing, and practice; responsible teaching adapts movements and avoids forcing range.","Zookeeper":"Animal-care professional feeds, observes, enriches, cleans, records, and supports veterinary/conservation work; animals remain wild/non-pet.","Sanitation Worker":"Worker supports public cleanliness and waste systems; exact tasks vary by municipality.",}
ACTIONS={k:"Point to the worker picture; name the job—do not imitate hazardous procedures." for k in ("Dentist","Electrician","Firefighter","Mechanic","Police Officer","Rescue Worker","Utility Worker","X-ray Technician","EMT","Lifeguard","Plumber","Veterinarian","Doctor","Nurse","Welder","Zookeeper")}
ACTIONS.update({"Ambulance":"Point to the vehicle; say it is not a job title.","Judge":"Point; make no arrest/punishment role-play.","Hairdresser":"Point; no scissors/heat mime.","Yard Worker":"Point; no mower/blade mime.","Zumba Instructor":"Show one gentle step only; no intensity challenge.","Yoga Teacher":"Show a comfortable standing pose; no forced stretch."})
